<?php
if(!defined('ABSPATH'))exit;
function dgs_quiz_url($year,$args=array()){return add_query_arg(array_merge(array('dg_tab'=>'quizzes','dg_year'=>$year),$args),dgs_page_url('portal'));}
function dgs_quiz_heading($title,$subtitle){return '<header class="dgq-heading"><small>خانه ‹ آزمون‌ها و کوییزها</small><h2>'.dgs_icon('book').' '.esc_html($title).'</h2><p>'.esc_html($subtitle).'</p></header>';}
function dgs_quiz_script_data($id,$data){return '<script type="application/json" id="'.esc_attr($id).'">'.wp_json_encode($data,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT).'</script>';}
function dgs_edu_view_quizzes($year){return dgs_quiz_portal($year);}
function dgs_quiz_portal($year){
 $manager=current_user_can('dgs_manage_education')||dgs_edu_role(get_current_user_id(),'dgs_teacher');$student=dgs_edu_role(get_current_user_id(),'dgs_student');if(!$manager&&!$student)return '';
 $id=absint(dgs_att_get('quiz_id'));$view=dgs_att_get('quiz_view');$q=$id?dgs_quiz_row($id):null;
 $out='<div class="dgq-quizzes">';if(dgs_att_get('quiz_saved')==='1')$out.='<p class="dgq-success">کوییز ذخیره شد.</p>';
 if($manager&&$view==='edit')return $out.dgs_quiz_builder($year,$q,$id).'</div>';
 if($id&&$view==='result')return $out.dgs_quiz_result_view($year,$q).'</div>';
 if($student&&$id&&$view==='take')return $out.dgs_quiz_take($year,$q).'</div>';
 return $out.dgs_quiz_list($year,$manager).'</div>';
}
function dgs_quiz_list($year,$manager){
 global $wpdb;$t=dgs_quiz_tables();$e=dgs_edu_tables();$uid=get_current_user_id();$args=array($year);$scope='';
 if($manager&&!current_user_can('dgs_manage_education')){$scope=" AND q.teacher_id=%d AND EXISTS (SELECT 1 FROM {$e['teaching']} a WHERE a.class_id=q.class_id AND a.subject_id=q.subject_id AND a.teacher_id=%d)";$args[]=$uid;$args[]=$uid;}
 elseif(!$manager){$scope=" AND q.status='published' AND (EXISTS (SELECT 1 FROM {$e['enrollments']} e WHERE e.class_id=q.class_id AND e.student_id=%d AND e.school_year=q.school_year) OR EXISTS (SELECT 1 FROM {$t['attempts']} a WHERE a.quiz_id=q.id AND a.student_id=%d))";$args[]=$uid;$args[]=$uid;}
 $rows=$wpdb->get_results($wpdb->prepare("SELECT q.*,c.title AS class_title,s.title AS subject,u.display_name AS teacher,(SELECT COUNT(*) FROM {$t['questions']} x WHERE x.quiz_id=q.id) AS qn FROM {$t['quizzes']} q JOIN {$e['classes']} c ON c.id=q.class_id JOIN {$e['subjects']} s ON s.id=q.subject_id LEFT JOIN {$wpdb->users} u ON u.ID=q.teacher_id WHERE q.school_year=%s $scope ORDER BY q.opens_at DESC,q.id DESC LIMIT 101",$args));
 $out=dgs_quiz_heading($manager?'کوییزهای کلاس':'آزمون‌ها و کوییزهای من',$manager?'ساخت کوییز تک‌درس برای کلاس‌های تخصیص‌یافته و مشاهده نتایج':'آزمون‌های کلاس شما با بازه دسترسی و زمان پاسخ‌گویی مشخص');
 if($manager)$out.='<a class="dg-btn" href="'.esc_url(dgs_quiz_url($year,array('quiz_view'=>'edit'))).'">＋ ساخت کوییز برای کلاس</a>';
 $out.='<form method="get" class="dge-filter" action="'.esc_url(dgs_page_url('portal')).'"><input type="hidden" name="dg_tab" value="quizzes"><label>سال تحصیلی<input name="dg_year" value="'.esc_attr($year).'" dir="ltr" required></label><button class="dg-btn dg-btn-outline">نمایش</button></form>';
 if(count($rows)>100)$out.='<p>۱۰۰ کوییز آخر نمایش داده می‌شود.</p>';$groups=array('active'=>array(),'future'=>array(),'ended'=>array(),'draft'=>array());$now=time();
 foreach(array_slice($rows,0,100) as $q){$a=$manager?null:dgs_quiz_attempt($q->id,$uid);if($a&&!$a->submitted_at&&$now>=(int)$a->deadline){$done=dgs_quiz_finish($q,$a);if(!is_wp_error($done))$a=$done;}
  $state=$q->status==='draft'?'draft':(($a&&$a->submitted_at)||$now>=(int)$q->closes_at?'ended':($now<(int)$q->opens_at?'future':'active'));$groups[$state][]=array($q,$a);
 }
 $labels=array('active'=>'▷ قابل شرکت / در حال برگزاری','future'=>'◷ آزمون‌های آینده','ended'=>'✓ آزمون‌های پایان‌یافته','draft'=>'پیش‌نویس‌ها');$out.='<nav class="dgq-state-nav">';foreach($labels as $key=>$label)if($key!=='draft'||$manager)$out.='<a href="#dgq-'.$key.'">'.$label.' ('.esc_html(dgs_fa_digits(count($groups[$key]))).')</a>';$out.='</nav>';
 foreach($labels as $state=>$label){if($state==='draft'&&!$manager)continue;$out.='<section id="dgq-'.$state.'"><h3 class="dgq-group-title">'.$label.'</h3>';foreach($groups[$state] as $item){list($q,$a)=$item;$out.='<article class="dgq-list-card"><div class="dgq-subject">'.dgs_icon('book').'<strong>'.esc_html($q->subject).'</strong><small>'.esc_html($q->class_title).'</small></div><div class="dgq-list-info"><h3>'.esc_html($q->title).'</h3><p>دبیر: '.esc_html($q->teacher??'').'</p><small>بازه دسترسی: '.esc_html(dgs_fa_digits(dgs_att_jdate(wp_date('Y-m-d',$q->opens_at)).' '.wp_date('H:i',$q->opens_at).' تا '.dgs_att_jdate(wp_date('Y-m-d',$q->closes_at)).' '.wp_date('H:i',$q->closes_at))).'</small></div><div class="dgq-list-meta"><span>'.esc_html(dgs_fa_digits($q->qn)).' سؤال</span><span>'.esc_html(dgs_fa_digits($q->duration)).' دقیقه</span></div><div class="dgq-list-action">';
   if($manager){$view=$q->status==='draft'?'edit':'result';$out.='<a class="dg-btn '.($view==='edit'?'dg-btn-outline':'').'" href="'.esc_url(dgs_quiz_url($year,array('quiz_id'=>$q->id,'quiz_view'=>$view))).'">'.($view==='edit'?'ویرایش پیش‌نویس':'نتایج و مشخصات').'</a>';}
   elseif($a&&$a->submitted_at)$out.='<a class="dg-btn" href="'.esc_url(dgs_quiz_url($year,array('quiz_id'=>$q->id,'quiz_view'=>'result'))).'">مشاهده نتیجه</a>';
   elseif($state==='active')$out.='<a class="dg-btn" href="'.esc_url(dgs_quiz_url($year,array('quiz_id'=>$q->id,'quiz_view'=>'take'))).'">'.($a?'ادامه آزمون':'شروع آزمون').' ▷</a>';
   else $out.='<span class="dgq-muted">'.($state==='future'?'هنوز شروع نشده':'بازه شرکت پایان یافته').'</span>';
   $out.='</div></article>';}
   if(!$groups[$state])$out.='<p class="dgq-muted">موردی در این بخش وجود ندارد.</p>';$out.='</section>';
 }return $out;
}
function dgs_quiz_builder($year,$q,$requested_id){
 if($requested_id&&(!$q||!dgs_quiz_manage($q)||$q->status!=='draft'||$q->school_year!==$year))return '<p class="dge-error">به ویرایش این پیش‌نویس دسترسی ندارید.</p>';
 $pairs=dgs_grade_pairs($year);$options=array();foreach($pairs as $p)$options[$p->class_id.':'.$p->subject_id]=$p->title.' — '.$p->subject;
 if(!$pairs)return '<p>ابتدا کلاس و درس را به دبیر تخصیص دهید.</p>';
 $start=$q?(int)$q->opens_at:time()+3600;$end=$q?(int)$q->closes_at:time()+7200;$questions=array();if($q)foreach(dgs_quiz_questions($q->id,true) as $item)$questions[]=array('id'=>(int)$item->id,'prompt'=>$item->prompt,'options'=>json_decode($item->options,true),'correct'=>(int)$item->correct,'weight'=>(int)$item->weight/100,'explanation'=>$item->explanation,'image'=>$item->image_mime?dgs_quiz_image_url($q->id,$item->id):'');
 $out=dgs_quiz_heading('ساخت کوییز برای کلاس','آزمون تک‌درس با سؤال‌های چهارگزینه‌ای، تصویر اختیاری و زمان‌بندی مشخص').'<a class="dg-btn dg-btn-outline" href="'.esc_url(dgs_quiz_url($year)).'">← بازگشت به کوییزها</a><form id="dgq-builder"><section class="dgq-card"><h3>☷ اطلاعات کوییز</h3><div class="dgq-grid">'.dgs_edu_select('pair','کلاس و درس',$options,$q?$q->class_id.':'.$q->subject_id:array_key_first($options)).'<label>عنوان کوییز<input name="title" maxlength="150" value="'.esc_attr($q?$q->title:'').'" required></label><label>تاریخ برگزاری (شمسی)<input name="open_date" dir="ltr" value="'.esc_attr(dgs_att_jdate(wp_date('Y-m-d',$start))).'" required></label><label>ساعت شروع<input name="open_time" type="time" value="'.esc_attr(wp_date('H:i',$start)).'" required></label><label>تاریخ پایان دسترسی (شمسی)<input name="close_date" dir="ltr" value="'.esc_attr(dgs_att_jdate(wp_date('Y-m-d',$end))).'" required></label><label>ساعت پایان دسترسی<input type="time" name="close_time" value="'.esc_attr(wp_date('H:i',$end)).'" required></label><label>مدت پاسخ‌گویی (دقیقه)<input type="number" name="duration" min="1" max="180" value="'.($q?(int)$q->duration:20).'" required></label></div><p class="dgq-help">ساعت‌ها به وقت تنظیمات وردپرس: '.esc_html(wp_timezone_string()).'. زمان هر نفر حداکثر تا پایان بازه دسترسی است.</p><div class="dgq-banner">کوییز یک کلاس و یک درس دارد. پس از انتشار، سؤال و زمان‌بندی قفل می‌شوند؛ پیش‌نمایش را قبل از انتشار بررسی کنید.</div></section><section class="dgq-card"><h3>◉ ویرایشگر سؤال</h3><div class="dgq-question-editor"><div><label>متن سؤال<textarea id="dgq-prompt" maxlength="2000" rows="3"></textarea></label><div class="dgq-options-editor">';
 for($i=1;$i<=4;$i++)$out.='<label>گزینه '.dgs_fa_digits($i).'<input data-q-option="'.$i.'" maxlength="500"></label>';
 $out.='</div><div class="dgq-grid"><label>پاسخ صحیح<select id="dgq-correct">';for($i=1;$i<=4;$i++)$out.='<option value="'.$i.'">گزینه '.dgs_fa_digits($i).'</option>';
 $out.='</select></label><label>نمره / وزن سؤال<input id="dgq-weight" type="number" min="0.01" max="100" step="0.01" value="1"></label></div><label>توضیح پاسخ (نمایش پس از پایان بازه)<textarea id="dgq-explanation" maxlength="2000" rows="2"></textarea></label></div><aside class="dgq-image-box"><label>تصویر سؤال (اختیاری)<input type="file" id="dgq-image-file" accept="image/png,image/jpeg"></label><img id="dgq-image-preview" alt="پیش‌نمایش تصویر سؤال" hidden><button type="button" class="dg-btn dg-btn-outline" id="dgq-image-remove">حذف تصویر</button><small>PNG یا JPG؛ حداکثر ۲ مگابایت. تصویر با کنترل دسترسی از سرور دریافت می‌شود.</small></aside></div><div class="dgq-actions"><button type="button" class="dg-btn" id="dgq-question-add">＋ افزودن سؤال به فهرست</button><button type="button" class="dg-btn dg-btn-outline" id="dgq-question-reset">سؤال جدید</button></div></section><section class="dgq-card"><h3>☷ فهرست سؤالات <span id="dgq-question-count"></span></h3><div class="dge-table-wrap"><table class="dge-table"><thead><tr><th>ردیف</th><th>متن سؤال (خلاصه)</th><th>نمره</th><th>عملیات / ترتیب</th></tr></thead><tbody id="dgq-question-list"></tbody></table></div><p id="dgq-total-weight"></p></section><section id="dgq-preview" class="dgq-card" hidden><h3>پیش‌نمایش محلی سؤالات</h3><div></div></section><p id="dgq-builder-status" role="status"></p><footer class="dgq-actions"><button class="dg-btn" type="button" id="dgq-publish">انتشار کوییز 🚀</button><button type="button" class="dg-btn dg-btn-outline" id="dgq-show-preview">◉ پیش‌نمایش</button><button type="button" class="dg-btn dg-btn-outline" id="dgq-save-draft">ذخیره به‌عنوان پیش‌نویس</button></footer></form>';
 return $out.dgs_quiz_script_data('dgq-builder-data',array('id'=>$q?(int)$q->id:0,'revision'=>$q?(int)$q->revision:0,'year'=>$year,'questions'=>$questions));
}
function dgs_quiz_take($year,$q){
 if(!$q||$q->school_year!==$year||(!dgs_quiz_member($q)&&!dgs_quiz_attempt($q->id,get_current_user_id())))return '<p class="dge-error">به این کوییز دسترسی ندارید.</p>';
 $a=dgs_quiz_attempt($q->id,get_current_user_id());$out=dgs_quiz_heading('شرکت در کوییز','پاسخ‌ها را انتخاب و در پایان، آزمون را ثبت کنید. فقط یک نوبت شرکت مجاز است.');
 $out.='<section class="dgq-card dgq-start-card" id="dgq-start-card"><h3>'.esc_html($q->title).'</h3><p>مدت: '.esc_html(dgs_fa_digits($q->duration)).' دقیقه؛ زمان واقعی باقی‌مانده از پایان بازه دسترسی بیشتر نمی‌شود.</p><button class="dg-btn" id="dgq-start" type="button">'.($a?'بازیابی و ادامه آزمون':'شروع آزمون').' ▷</button></section><div id="dgq-take" hidden><div class="dgq-take-layout"><section class="dgq-card dgq-current"><div class="dgq-question-header"><strong>'.esc_html($q->title).'</strong><span id="dgq-current-number"></span></div><h3 id="dgq-current-prompt"></h3><img id="dgq-current-image" alt="تصویر سؤال" hidden><fieldset id="dgq-current-options"><legend class="screen-reader-text">انتخاب پاسخ سؤال</legend></fieldset><button type="button" class="dgq-clear" id="dgq-clear">پاک‌کردن پاسخ این سؤال</button><p class="dgq-save-state" id="dgq-save-state" role="status"></p><div class="dgq-actions"><button class="dg-btn dg-btn-outline" type="button" id="dgq-prev">→ سؤال قبلی</button><button class="dg-btn" type="button" id="dgq-next">سؤال بعدی ←</button></div></section><aside><section class="dgq-card dgq-clock-card"><h3>◷ زمان باقی‌مانده</h3><strong id="dgq-timer">--:--</strong></section><section class="dgq-card"><h3>☷ نقشه سؤالات</h3><div id="dgq-question-map"></div><p id="dgq-answered-count"></p><div class="dgq-progress"><i id="dgq-progress-fill"></i></div><button id="dgq-submit" class="dg-btn" type="button">✓ پایان و ثبت آزمون</button><button id="dgq-retry" class="dg-btn dg-btn-outline" type="button" hidden>تلاش دوباره برای ذخیره</button></section></aside></div></div><p id="dgq-take-error" class="dgq-error" role="alert" hidden></p>';
 return $out.dgs_quiz_script_data('dgq-take-data',array('id'=>(int)$q->id,'year'=>$year));
}
function dgs_quiz_result_view($year,$q){
 if(!$q||$q->school_year!==$year)return '<p class="dge-error">کوییز پیدا نشد.</p>';$manager=dgs_quiz_manage($q);$uid=get_current_user_id();$out=dgs_quiz_heading('نتیجه کوییز',$q->title).'<a class="dg-btn dg-btn-outline" href="'.esc_url(dgs_quiz_url($year)).'">← بازگشت به آزمون‌ها</a>';
 global $wpdb;$t=dgs_quiz_tables();
 if($manager){$rows=$wpdb->get_results($wpdb->prepare("SELECT a.*,u.display_name FROM {$t['attempts']} a JOIN {$wpdb->users} u ON u.ID=a.student_id WHERE a.quiz_id=%d ORDER BY u.display_name LIMIT 201",$q->id));$selected=absint(dgs_att_get('quiz_student'));$out.='<section class="dgq-card"><h3>نتایج شرکت‌کنندگان</h3><p>زمان‌بندی و سؤال‌های کوییز منتشرشده قابل تغییر نیستند. حداکثر ۲۰۰ شرکت‌کننده در گزارش نمایش داده می‌شود.</p>'.dgs_edu_table_start(array('دانش‌آموز','وضعیت','نمره از ۲۰','عملیات'));$chosen=null;
  foreach(array_slice($rows,0,200) as $a){if(!$a->submitted_at&&time()>=(int)$a->deadline){$done=dgs_quiz_finish($q,$a);if(!is_wp_error($done)){$done->display_name=$a->display_name;$a=$done;}}$r=json_decode($a->result,true);if((int)$a->student_id===$selected)$chosen=$a;$out.='<tr><td>'.esc_html($a->display_name).'</td><td>'.($a->submitted_at?'نهایی‌شده':'در حال پاسخ‌گویی').'</td><td>'.($a->submitted_at?esc_html(dgs_fa_digits($r['grade']??0)):'—').'</td><td><a href="'.esc_url(dgs_quiz_url($year,array('quiz_id'=>$q->id,'quiz_view'=>'result','quiz_student'=>$a->student_id))).'">بررسی پاسخ‌ها</a></td></tr>';}
  $out.='</tbody></table></div></section>';if(!$chosen)return $out;$a=$chosen;
 }else{
  if(!dgs_edu_role($uid,'dgs_student'))return '<p class="dge-error">دسترسی مجاز نیست.</p>';$a=dgs_quiz_attempt($q->id,$uid);if(!$a)return $out.'<p>شما در این کوییز شرکت نکرده‌اید.</p>';if(!$a->submitted_at&&time()>=(int)$a->deadline){$a=dgs_quiz_finish($q,$a);if(is_wp_error($a))return $out.'<p>صفحه را تازه کنید.</p>';}
 }
 $payload=dgs_quiz_result_payload($q,$a);if(is_wp_error($payload))return $out.'<p>'.esc_html($payload->get_error_message()).'</p>';
 if($payload['pending'])return $out.'<section class="dgq-card"><div class="dgq-banner">✓ پاسخ‌های شما ثبت شد.</div><p>نتیجه و کلید پس از پایان بازه آزمون منتشر می‌شود: '.esc_html(dgs_fa_digits(dgs_att_jdate(wp_date('Y-m-d',$q->closes_at)).' '.wp_date('H:i',$q->closes_at))).'</p></section>';
 $r=$payload['result'];$answers=$payload['answers']?:array();$subject=get_userdata($q->teacher_id);$meta=dgs_edu_subjects();$subject_title='';foreach($meta as $s)if((int)$s->id===(int)$q->subject_id)$subject_title=$s->title;
 $out.='<div id="dgq-result-report"><div class="dgq-banner">✓ کوییز با موفقیت ثبت شد. '.($manager?'دانش‌آموز: '.esc_html(get_userdata($a->student_id)->display_name):'نتیجه و بررسی پاسخ‌های شما در ادامه قابل مشاهده است.').'</div><div class="dgq-result-grid"><section class="dgq-card"><dl><dt>درس</dt><dd>'.esc_html($subject_title).'</dd><dt>دبیر</dt><dd>'.esc_html($subject?$subject->display_name:'').'</dd><dt>تاریخ برگزاری</dt><dd>'.esc_html(dgs_fa_digits(dgs_att_jdate(wp_date('Y-m-d',$q->opens_at)))).'</dd><dt>مدت آزمون</dt><dd>'.esc_html(dgs_fa_digits($q->duration)).' دقیقه</dd><dt>نوع</dt><dd>کوییز تک‌درس</dd></dl></section><section class="dgq-card dgq-result-score"><div class="dgq-ring" style="--dgq-pct:'.((float)$r['grade']*5).'%"><strong>'.esc_html(dgs_fa_digits($r['grade'])).'<small>از ۲۰</small></strong></div><div><p class="dgq-green">✓ '.esc_html(dgs_fa_digits($r['correct'])).' پاسخ صحیح</p><p class="dgq-red">× '.esc_html(dgs_fa_digits($r['wrong'])).' پاسخ نادرست</p><p>'.esc_html(dgs_fa_digits($r['blank'])).' بدون پاسخ</p></div></section></div><section class="dgq-card"><h3>▥ خلاصه عملکرد شما</h3><div class="dgq-performance">';
 foreach(array('correct'=>array('صحیح','green'),'wrong'=>array('نادرست','red'),'blank'=>array('بدون پاسخ','gray')) as $key=>$v)$out.='<div><strong>'.esc_html(dgs_fa_digits($r[$key])).'</strong><i class="dgq-'.$v[1].'-bar" style="height:'.(count($payload['questions'])?max(3,$r[$key]/count($payload['questions'])*110):3).'px"></i><span>'.$v[0].'</span></div>';
 $out.='<aside>نمره نهایی <strong>'.esc_html(dgs_fa_digits($r['grade'])).' از ۲۰</strong><small>پاسخ صحیح: '.esc_html(dgs_fa_digits($r['percent'])).'٪</small></aside></div><p class="dgq-help">نمره بر اساس وزن سؤال‌های صحیح و بدون نمره منفی محاسبه شده است. درصد پاسخ صحیح، نسبت تعداد پاسخ صحیح به کل سؤال‌هاست.</p></section><section class="dgq-card"><h3>☷ بررسی سؤال به سؤال</h3>'.dgs_edu_table_start(array('شماره','سؤال','پاسخ شما','پاسخ صحیح','وضعیت','توضیحات'));$i=0;
 foreach($payload['questions'] as $question){$i++;$answer=(int)($answers[$question->id]??0);$status=!$answer?'بدون پاسخ':($answer===(int)$question->correct?'صحیح':'نادرست');$out.='<tr><td>'.esc_html(dgs_fa_digits($i)).'</td><td>'.nl2br(esc_html($question->prompt)).($question->image_mime?'<img class="dgq-result-image" src="'.esc_url(dgs_quiz_image_url($q->id,$question->id)).'" alt="تصویر سؤال">':'').'<small class="dgq-result-options">';foreach(json_decode($question->options,true) as $oi=>$option)$out.=esc_html(dgs_fa_digits($oi+1).': '.$option).'<br>';$out.='</small></td><td>'.($answer?'گزینه '.esc_html(dgs_fa_digits($answer)):'—').'</td><td>گزینه '.esc_html(dgs_fa_digits($question->correct)).'</td><td class="'.($status==='صحیح'?'dgq-green':($answer?'dgq-red':'')).'">'.$status.'</td><td>'.nl2br(esc_html($question->explanation)).'</td></tr>';}
 return $out.'</tbody></table></div></section></div><button class="dg-btn" type="button" data-quiz-print>دریافت / چاپ گزارش ↓</button>';
}
add_filter('body_class',function($classes){if(dgs_is_role_portal()&&dgs_portal_tab()==='quizzes')$classes[]='dgs-quizzes-page';return $classes;});
add_action('wp_enqueue_scripts',function(){
 if(!dgs_is_role_portal()||dgs_portal_tab()!=='quizzes')return;
 wp_register_style('dgs-quizzes',false,array(),DGS_VERSION);wp_enqueue_style('dgs-quizzes');wp_add_inline_style('dgs-quizzes',file_get_contents(DGS_PATH.'assets/quizzes.css'));
 wp_register_script('dgs-quizzes',false,array(),DGS_VERSION,true);wp_enqueue_script('dgs-quizzes');wp_add_inline_script('dgs-quizzes','window.dgsQuizConfig='.wp_json_encode(array('ajax'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('dgs_quiz'),'portal'=>dgs_page_url('portal'))).';'.file_get_contents(DGS_PATH.'assets/quizzes.js'));
});
